const container = document.getElementById('menu-container');
const modal = document.getElementById('imageModal');
const modalImg = document.getElementById('modalImage');
const modalClose = document.getElementById('modalClose');

let focusedElementBeforeModal = null; // モーダルを開く前にフォーカスされていた要素を保存

const renderMenu = (category = 'all') => {
  container.innerHTML = '';
  menuData.filter(item => category === 'all' || item.category === category)
    .forEach(item => {
      // Schema.org MenuItem 構造化データを生成
      const menuItemSchema = {
        "@context": "http://schema.org",
        "@type": "MenuItem",
        "name": item.name.replace(/【仮】/g, ''), // 【仮】を削除
        "description": item.desc,
        "image": `https://jyuan.jp/${item.image}`, // 絶対パスに変換
        "offers": {
          "@type": "Offer",
          "price": item.price === "準備中" ? "0" : item.price.toString(), // 価格が準備中の場合も対応
          "priceCurrency": "JPY"
        }
      };

      container.innerHTML += `
        <div class="bg-white shadow rounded-lg overflow-hidden flex flex-col md:flex-row relative menu-item-card">
          ${item.badge ? `<div class="badge">${item.badge}</div>` : ''}
          <picture>
            <source srcset="${item.image}" type="image/webp">
            <img src="${item.image.replace('.webp', '.jpg')}" alt="${item.name}" class="w-full md:w-1/3 object-cover cursor-pointer"
                 onclick="openModal('${item.image}')"
                 tabindex="0"
                 onkeydown="if(event.key === 'Enter' || event.key === ' '){ event.preventDefault(); openModal('${item.image}'); }"
                 loading="lazy">
          </picture>
          <div class="p-4 flex flex-col justify-between">
            <div>
              <h3 class="text-xl font-bold text-red-700 mb-2">${item.name}</h3>
              <p class="text-sm text-gray-600 mb-2">${item.desc}</p>
            </div>
            <div class="mt-4 text-right font-semibold text-gray-800">${item.price}円（税込）</div>
          </div>
          <script type="application/ld+json">${JSON.stringify(menuItemSchema)}</script>
        </div>
      `;
    });
};

document.querySelectorAll('.filter-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('bg-red-300'));
    btn.classList.add('bg-red-300');
    renderMenu(btn.dataset.category);
  });
  btn.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('bg-red-300'));
      btn.classList.add('bg-red-300');
      renderMenu(btn.dataset.category);
    }
  });
});

renderMenu(); // 初期メニュー表示

function openModal(imgSrc) {
    focusedElementBeforeModal = document.activeElement; // 現在フォーカスされている要素を保存

    modal.style.display = "block";
    modalImg.src = imgSrc;
    modalImg.alt = imgSrc.split('/').pop().split('.')[0]; // ファイル名からaltを設定 (必要に応じてより詳細に)
    modalImg.style.transform = "scale(1)";
    setTimeout(() => {
        modalImg.style.transform = "scale(1.05)";
    }, 50);

    // モーダルが開いたら、閉じるボタンにフォーカスを移動
    document.getElementById('modalClose').focus();

    // フォーカストラップのイベントリスナーを追加
    document.addEventListener('keydown', trapTabKey);
}

function closeModal() {
    modal.style.display = "none";
    modalImg.style.transform = "scale(1)";

    // フォーカストラップのイベントリスナーを削除
    document.removeEventListener('keydown', trapTabKey);

    // モーダルを閉じた後、元の要素にフォーカスを戻す
    if (focusedElementBeforeModal) {
        focusedElementBeforeModal.focus();
    }
}

modalClose.onclick = closeModal;
modalClose.addEventListener('keydown', function (event) {
  if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    closeModal();
  } else if (event.key === 'Escape') {
    event.preventDefault();
    closeModal();
  }
});

window.onclick = function(event) {
  if (event.target === modal) {
    closeModal();
  }
};
window.addEventListener('keydown', function(event) {
    if (event.key === 'Escape' && modal.style.display === "block") {
        closeModal();
    }
});

// フォーカストラップの実装
function trapTabKey(e) {
    if (e.key === 'Tab') {
        const focusableElements = modal.querySelectorAll(
            'a[href], button, input, textarea, select, details,[tabindex]:not([tabindex="-1"])'
        );
        const firstFocusableEl = focusableElements[0];
        const lastFocusableEl = focusableElements[focusableElements.length - 1];

        if (e.shiftKey) { // Shift + Tab (逆方向)
            if (document.activeElement === firstFocusableEl || document.activeElement === modal) {
                lastFocusableEl.focus();
                e.preventDefault();
            }
        } else { // Tab (順方向)
            if (document.activeElement === lastFocusableEl) {
                firstFocusableEl.focus();
                e.preventDefault();
            }
        }
    }
}

// ===== index.html の <script> ブロックの内容を統合 =====
document.addEventListener("DOMContentLoaded", () => {
  // ヒーロースライダー (CSSアニメーション制御)
  let currentHero = 0;
  const heroImages = document.querySelectorAll("#heroSlider .hero-slide");
  const numImages = heroImages.length;

  heroImages[currentHero].classList.add("active"); // 初期状態を設定

  setInterval(() => {
    heroImages[currentHero].classList.remove("active");
    currentHero = (currentHero + 1) % numImages;
    heroImages[currentHero].classList.add("active");
  }, 5000);

  // モバイルメニュー開閉
  // toggleMenu, closeMenuOnOutsideClick, closeMobileMenu 関数は別途定義

  // セクションh2の開閉機能 (アクセシビリティ対応)
  document.querySelectorAll('section').forEach(section => {
    const h2 = section.querySelector('h2');
    if (h2) {
      h2.classList.add('cursor-pointer');
      h2.tabIndex = 0; // tabindex="0" を追加
      const bodyElements = Array.from(section.children).filter(el => el !== h2);
      if (bodyElements.length > 0) {
        h2.onclick = () => {
          bodyElements.forEach(el => el.classList.toggle('hidden'));
        };
        h2.addEventListener('keydown', (event) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            bodyElements.forEach(el => el.classList.toggle('hidden'));
          }
        });
      }
    }
  });

  // 内外観スライダー (Intersection Observer & 自動切り替え)
  const exteriorImages = [
    "images/exterior1.webp", // 画像パスをWebPに調整
    "images/exterior2.webp",
    "images/exterior3.webp"
  ];
  let currentExterior = 0;
  const exteriorSlide = document.getElementById("exteriorSlide");
  let exteriorIntervalId = null;

  function updateExteriorSlide() {
    exteriorSlide.src = exteriorImages[currentExterior];
    exteriorSlide.alt = `店舗外観 ${currentExterior + 1}`;
  }

  function nextExteriorSlide() {
    currentExterior = (currentExterior + 1) % exteriorImages.length;
    updateExteriorSlide();
  }

  function prevExteriorSlide() {
    currentExterior = (currentExterior - 1 + exteriorImages.length) % exteriorImages.length;
    updateExteriorSlide();
  }

  const prevExteriorBtn = document.getElementById('prevExteriorBtn');
  const nextExteriorBtn = document.getElementById('nextExteriorBtn');

  if(prevExteriorBtn && nextExteriorBtn && exteriorSlide) {
      prevExteriorBtn.addEventListener('click', prevExteriorSlide);
      prevExteriorBtn.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); prevExteriorSlide(); } });
      nextExteriorBtn.addEventListener('click', nextExteriorSlide);
      nextExteriorBtn.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); nextExteriorSlide(); } });
      exteriorSlide.addEventListener('click', nextExteriorSlide);
      exteriorSlide.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); nextExteriorSlide(); } });
  }

  const exteriorObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        if (exteriorSlide && exteriorSlide.dataset.src && !exteriorSlide.src) {
           exteriorSlide.src = exteriorSlide.dataset.src;
           exteriorSlide.alt = exteriorSlide.alt || `店舗外観 ${currentExterior + 1}`;
        }
        if (!exteriorIntervalId) {
          exteriorIntervalId = setInterval(nextExteriorSlide, 3000);
        }
      } else {
        if (exteriorIntervalId) {
          clearInterval(exteriorIntervalId);
          exteriorIntervalId = null;
        }
      }
    });
  }, { threshold: 0.1 });
  if (document.getElementById("exterior")) {
    exteriorObserver.observe(document.getElementById("exterior"));
  }

  const interiorImages = [
    "images/interior1.webp", // 画像パスをWebPに調整
    "images/interior2.webp",
    "images/interior3.webp",
    "images/interior4.webp",
    "images/interior5.webp"
  ];
  let currentInterior = 0;
  const interiorSlide = document.getElementById("interiorSlide");
  let interiorIntervalId = null;

  function updateInteriorSlide() {
    interiorSlide.src = interiorImages[currentInterior];
    interiorSlide.alt = `店舗内観 ${currentInterior + 1}`;
  }

  function nextInteriorSlide() {
    currentInterior = (currentInterior + 1) % interiorImages.length;
    updateInteriorSlide();
  }

  function prevInteriorSlide() {
    currentInterior = (currentInterior - 1 + interiorImages.length) % interiorImages.length;
    updateInteriorSlide();
  }

  const prevInteriorBtn = document.getElementById('prevInteriorBtn');
  const nextInteriorBtn = document.getElementById('nextInteriorBtn');

  if(prevInteriorBtn && nextInteriorBtn && interiorSlide) {
      prevInteriorBtn.addEventListener('click', prevInteriorSlide);
      prevInteriorBtn.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); prevInteriorSlide(); } });
      nextInteriorBtn.addEventListener('click', nextInteriorSlide);
      nextInteriorBtn.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); nextInteriorSlide(); } });
      interiorSlide.addEventListener('click', nextInteriorSlide);
      interiorSlide.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); nextInteriorSlide(); } });
  }

  const interiorObserver = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        if (interiorSlide && interiorSlide.dataset.src && !interiorSlide.src) {
          interiorSlide.src = interiorSlide.dataset.src;
          interiorSlide.alt = interiorSlide.alt || `店舗内観 ${currentInterior + 1}`;
        }
        if (!interiorIntervalId) {
          interiorIntervalId = setInterval(nextInteriorSlide, 3000);
        }
      } else {
        if (interiorIntervalId) {
          clearInterval(interiorIntervalId);
          interiorIntervalId = null;
        }
      }
    });
  }, { threshold: 0.1 });
  if (document.getElementById("interior")) {
    interiorObserver.observe(document.getElementById("interior"));
  }

  // Google Mapsの動的ロード
  const mapSection = document.getElementById("access");
  const mapIframe = document.getElementById("googleMapIframe");

  if (mapSection && mapIframe) {
    const mapObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          if (mapIframe.dataset.src && !mapIframe.src) {
            mapIframe.src = mapIframe.dataset.src;
            mapIframe.removeAttribute('data-src');
          }
          observer.unobserve(mapSection);
        }
      });
    }, {
      rootMargin: "0px 0px -100px 0px",
      threshold: 0
    });
    mapObserver.observe(mapSection);
  }
}); // DOMContentLoaded の終わり

// モバイルメニュー開閉関数 (グローバルにアクセスできるように)
function toggleMenu() {
  const nav = document.getElementById('navMobile');
  const toggleButton = document.querySelector('button[onclick="toggleMenu()"]');

  const isHidden = nav.classList.toggle('hidden');
  toggleButton.setAttribute('aria-expanded', !isHidden);

  if (!isHidden) {
    document.addEventListener('click', closeMenuOnOutsideClick);
  } else {
    document.removeEventListener('click', closeMenuOnOutsideClick);
  }
}

function closeMenuOnOutsideClick(event) {
  const nav = document.getElementById('navMobile');
  const button = event.target.closest('button[onclick="toggleMenu()"]');
  const insideNav = event.target.closest('#navMobile');
  if (!insideNav && !button) {
    nav.classList.add('hidden');
    document.removeEventListener('click', closeMenuOnOutsideClick);
    document.querySelector('button[onclick="toggleMenu()"]').setAttribute('aria-expanded', 'false');
  }
}

function closeMobileMenu() {
  const nav = document.getElementById('navMobile');
  nav.classList.add('hidden');
  document.removeEventListener('click', closeMenuOnOutsideClick);
  document.querySelector('button[onclick="toggleMenu()"]').setAttribute('aria-expanded', 'false');
}
